namespace SimpX.Net.Application.Shared;

/// <summary>旧 GameCategory 整型 ↔ 枚举名。</summary>
public static class GameCategoryNameMap
{
    private static readonly Dictionary<int, string> Names = new()
    {
        [0] = "Lottery",
        [1] = "ESport",
        [2] = "Slot",
        [3] = "Live",
        [4] = "Chess",
        [5] = "Sport",
        [6] = "Fish",
        [7] = "Animal",
        [8] = "MiniGame",
        [9] = "Battle",
    };

    /// <summary>整型 → 枚举名。</summary>
    public static string Format(int category) =>
        Names.TryGetValue(category, out var name) ? name : category.ToString();

    /// <summary>枚举名或数字 → 整型。</summary>
    public static bool TryParse(string? text, out int category)
    {
        category = -1;
        if (string.IsNullOrWhiteSpace(text)) return false;
        if (int.TryParse(text.Trim(), out category)) return true;
        foreach (var kv in Names)
        {
            if (string.Equals(kv.Value, text.Trim(), StringComparison.OrdinalIgnoreCase))
            {
                category = kv.Key;
                return true;
            }
        }

        return false;
    }
}
